int find_exterior_major(int leaf) {
    int cur = leaf, prev = -1;
    while (1) {
        if (deg[cur] >= 3) return cur;
        // find next vertex (not prev)
        int next = -1;
        for (int e = head[cur]; e != -1; e = nxt[e]) {
            if (to[e] != prev) { next = to[e]; break; }
        }
        if (next == -1) return cur; // reached other end (path case)
        prev = cur;
        cur = next;
    }
}

