typedef struct Edge {
    int to, next;
} Edge;

static int N;
static Edge *edges;
static int *head;
static int ecnt = 0;

static void add_edge(int u, int v) {
    edges[ecnt].to = v;
    edges[ecnt].next = head[u];
    head[u] = ecnt++;
}

static int *deg_;
static int *removed_;
static int *subsz;
static int *parent_centroid;
static int *mark_;
static int *queue_;
static int *order_;

static int *is_antenna;
static int answer = 0;

/* Gather component vertices starting from start, ignoring removed vertices. */
static int get_component(int start) {
    int qh = 0, qt = 0, sz = 0;
    queue_[qt++] = start;
    parent_centroid[start] = -2; /* temporary visited mark for this BFS */
    while (qh < qt) {
        int v = queue_[qh++];
        order_[sz++] = v;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (removed_[to]) continue;
            if (parent_centroid[to] == -2) continue;
            parent_centroid[to] = -2;
            queue_[qt++] = to;
        }
    }
    /* clear temporary marks to -1 */
    for (int i = 0; i < sz; i++) parent_centroid[order_[i]] = -1;
    return sz;
}

/* Find centroid of component whose vertices are in order_[0..sz-1]. */
static int find_centroid(int sz) {
    for (int i = 0; i < sz; i++) subsz[order_[i]] = 0;

    int root = order_[0];
    int top = 0;
    queue_[top++] = root;
    parent_centroid[root] = -1;
    int ordsz = 0;

    while (ordsz < top) {
        int v = queue_[ordsz++];
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (removed_[to] || to == parent_centroid[v]) continue;
            parent_centroid[to] = v;
            queue_[top++] = to;
        }
    }

    for (int i = ordsz - 1; i >= 0; i--) {
        int v = queue_[i];
        subsz[v] = 1;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (removed_[to] || parent_centroid[to] != v) continue;
            subsz[v] += subsz[to];
        }
    }

    int centroid = root;
    int best = sz + 1;
    for (int i = 0; i < ordsz; i++) {
        int v = queue_[i];
        int mx = sz - subsz[v];
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (removed_[to] || parent_centroid[to] != v) continue;
            if (subsz[to] > mx) mx = subsz[to];
        }
        if (mx < best) {
            best = mx;
            centroid = v;
        }
    }

    return centroid;
}

/*
Key fact:
A set of vertices resolves a tree iff for every vertex of degree >= 3,
all but at most one of the branches incident to it contain at least one resolver.
Minimum size equals sum over branching vertices of (number of incident branch-paths needing coverage - 1),
which simplifies to the classic tree metric dimension formula:
- If the tree is a path, answer = 1.
- Otherwise, answer = (# leaves) - (# exterior major vertices),
where an exterior major vertex is a degree>=3 vertex that has at least one terminal leaf
(a leaf for which this major vertex is the closest major vertex).

We compute for each leaf, walk inward until first major vertex; mark that major vertex.
Then answer = leaves - marked_major_count.
*/

int main(void) {
    if (scanf("%d", &N) != 1) return 0;

    head = (int*)malloc(sizeof(int) * N);
    deg_ = (int*)calloc(N, sizeof(int));
    for (int i = 0; i < N; i++) head[i] = -1;

    edges = (Edge*)malloc(sizeof(Edge) * 2 * (N - 1));

    for (int i = 0; i < N - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        add_edge(a, b);
        add_edge(b, a);
        deg_[a]++;
        deg_[b]++;
    }

    if (N == 1) {
        printf("1\n");
        return 0;
    }

    int leaves = 0;
    int has_major = 0;
    for (int i = 0; i < N; i++) {
        if (deg_[i] == 1) leaves++;
        if (deg_[i] >= 3) has_major = 1;
    }

    if (!has_major) {
        /* Tree is a path */
        printf("1\n");
        return 0;
    }

    mark_ = (int*)calloc(N, sizeof(int));

    for (int leaf = 0; leaf < N; leaf++) {
        if (deg_[leaf] != 1) continue;
        int prev = -1;
        int cur = leaf;
        while (deg_[cur] < 3) {
            int nxt = -1;
            for (int e = head[cur]; e != -1; e = edges[e].next) {
                int to = edges[e].to;
                if (to == prev) continue;
                nxt = to;
                break;
            }
            prev = cur;
            cur = nxt;
        }
        mark_[cur] = 1;
    }

    int exterior_major = 0;
    for (int i = 0; i < N; i++) exterior_major += mark_[i];

    answer = leaves - exterior_major;
    printf("%d\n", answer);

    return 0;
}

