/*
We need the metric dimension of a tree.

For a tree:
- If N = 1, answer = 0.
- If the tree is a path, answer = 1.
- Otherwise, answer = sum over all major vertices v of (# of terminal leaves of v) - (# of major vertices with at least one terminal leaf),
  which is equivalent to:
    (# of leaves) - (# of exterior major vertices)

Definitions:
- leaf: degree 1
- major vertex: degree >= 3
- terminal leaf of a major vertex v: a leaf u such that among all major vertices, v is the unique closest one to u.
- exterior major vertex: major vertex having at least one terminal leaf.

For each leaf, walk inward until the first vertex whose degree != 2.
- If that vertex is major, then this leaf is terminal for that major vertex.
- In a non-path tree, every leaf belongs to exactly one exterior major vertex this way.

Then answer = leaves - count(major vertices that got at least one leaf).

This can be computed in O(N).
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();

        if (N == 1) {
            System.out.println(0);
            return;
        }

        int[] deg = new int[N];
        int[] eu = new int[N - 1];
        int[] ev = new int[N - 1];

        for (int i = 0; i < N - 1; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            eu[i] = a;
            ev[i] = b;
            deg[a]++;
            deg[b]++;
        }

        boolean isPath = true;
        int leaves = 0;
        for (int i = 0; i < N; i++) {
            if (deg[i] == 1) leaves++;
            if (deg[i] > 2) isPath = false;
        }

        if (isPath) {
            System.out.println(1);
            return;
        }

        int[] head = new int[N];
        Arrays.fill(head, -1);
        int[] to = new int[2 * (N - 1)];
        int[] next = new int[2 * (N - 1)];
        int idx = 0;
        for (int i = 0; i < N - 1; i++) {
            int a = eu[i], b = ev[i];
            to[idx] = b;
            next[idx] = head[a];
            head[a] = idx++;
            to[idx] = a;
            next[idx] = head[b];
            head[b] = idx++;
        }

        boolean[] exteriorMajor = new boolean[N];

        for (int leaf = 0; leaf < N; leaf++) {
            if (deg[leaf] != 1) continue;

            int prev = -1;
            int cur = leaf;

            while (deg[cur] == 1 || deg[cur] == 2) {
                int nxt = -1;
                for (int e = head[cur]; e != -1; e = next[e]) {
                    int w = to[e];
                    if (w != prev) {
                        nxt = w;
                        break;
                    }
                }
                prev = cur;
                cur = nxt;
            }

            // cur is the first non-degree-2 vertex encountered from the leaf.
            // In a non-path tree, this must be a major vertex.
            exteriorMajor[cur] = true;
        }

        int exteriorCount = 0;
        for (int i = 0; i < N; i++) {
            if (exteriorMajor[i]) exteriorCount++;
        }

        System.out.println(leaves - exteriorCount);
    }
}

