int main(){
    int n;
    cin >> n;

    if(n == 1){
        cout << 0 << endl;
        return 0;
    }

    vector<vector<int>> adj(n);
    vector<int> deg(n, 0);

    for(int i = 0; i < n-1; i++){
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
        deg[a]++;
        deg[b]++;
    }

    // Check if it's a path
    int leaves = 0;
    for(int i = 0; i < n; i++) if(deg[i] == 1) leaves++;

    if(leaves == 2){
        // It's a path
        cout << 1 << endl;
        return 0;
    }

    // For each leaf, find its exterior major vertex
    // Walk from leaf until we find a vertex with degree >= 3
    set<int> exterior_major;

    for(int i = 0; i < n; i++){
        if(deg[i] == 1){
            // BFS/walk from leaf
            int cur = i;
            int prev = -1;
            while(deg[cur] < 3){
                // move to next
                int nxt = -1;
                for(int nb : adj[cur]){
                    if(nb != prev){
                        nxt = nb;
                        break;
                    }
                }
                if(nxt == -1) break; // shouldn't happen in non-path tree
                prev = cur;
                cur = nxt;
            }
            if(deg[cur] >= 3){
                exterior_major.insert(cur);
            }
        }
    }

    int ex = exterior_major.size();
