#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<vector<int>> g(N);
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    if (N == 1) {
        cout << 0 << '\n';
        return 0;
    }

    vector<int> deg(N);
    queue<int> q;
    for (int i = 0; i < N; i++) {
        deg[i] = (int)g[i].size();
        if (deg[i] <= 1) q.push(i);
    }

    vector<int> removed(N, 0);
    int remaining = N;

    while (remaining > 2) {
        int sz = (int)q.size();
        remaining -= sz;
        for (int i = 0; i < sz; i++) {
            int v = q.front(); q.pop();
            removed[v] = 1;
            for (int to : g[v]) {
                if (removed[to]) continue;
                deg[to]--;
                if (deg[to] == 1) q.push(to);
            }
        }
    }

    vector<int> centers;
    for (int i = 0; i < N; i++) {
        if (!removed[i]) centers.push_back(i);
    }

    int answer = 0;
    for (int c : centers) {
        int cnt = 0;
        for (int to : g[c]) {
            if ((int)g[to].size() >= 2) cnt++;
        }
        answer = max(answer, cnt);
    }

    cout << answer << '\n';
    return 0;
}
